 document.addEventListener('DOMContentLoaded', () => {
     const quizForm = document.getElementById('quiz-form');
     const resultsContainer = document.getElementById('results');
     const scoreText = document.getElementById('score-text');
     const retryBtn = document.getElementById('retry-btn');

     const correctAnswers = {
         q1: ['cpp', 'rust', 'go'],
         q2: ['swift', 'kotlin', 'dart'],
         q3: ['assembly', 'c', 'rust']
     };

     quizForm.addEventListener('submit', (e) => {
         e.preventDefault();

         const formData = new FormData(quizForm);
         let score = 0;
         const totalQuestions = Object.keys(correctAnswers).length;

         for (const [question, correctChoices] of Object.entries(correctAnswers)) {
             const userChoices = formData.getAll(question);

             // Check if user selected exactly the correct ones
             const isCorrect = userChoices.length === correctChoices.length && 
                               userChoices.every(choice => correctChoices.includes(choice));

             if (isCorrect) {
                 score++;
             }
         }

         quizForm.classList.add('hidden');
         resultsContainer.classList.remove('hidden');
         scoreText.textContent = `You got ${score} out of ${totalQuestions} questions correct!`;
     });

     retryBtn.addEventListener('click', () => {
         quizForm.reset();
         quizForm.classList.remove('hidden');
         resultsContainer.classList.add('hidden');
         window.scrollTo({ top: 0, behavior: 'smooth' });
     });
 });

